INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (21, 1, 14, 17, 2, 10, 1, 1, 1, '<p style=\"margin:0\">Pra sidang atau Sidang tertutup telah dilaksanakan tanggal 22 Desember 2023, dan dihadiri Dosen Pembimbing Bapak Dr. Yadi Mulyadi, M.T., dan Bapak M.Adli Rizqullah, S.Pd, M.T., serta dihadiri Dosen Penguji Prof.Dr. Ade Gaffar A., M.Si, ibu Silmi Ath Thahirah A., M.T dan Bapak Wasimudin Surya, S.T., M.T.<br></p>', '2023-12-17 17:58:00', '2023-12-24 22:34:14');
