INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (26, 1, 37, 4, 4, 3, 1, 1, 1, '<p style=\"margin:0\">penambahan isi di bab 2<br>perubahan format tabel pada bab 4 dari poptrait menjadi landscape<br>penambahan dan perubahan pada bab 5 bagian simpulan<br>penambahan daftar pustaka&nbsp;<br><br></p>', '2023-12-21 08:40:39', '2024-01-04 00:43:19');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (27, 1, 58, 5, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Penguji 1<br>-Perbaiki Kepala tabel<br>-Pada abstrak belum adanya problem utama<br>-Pada teori belum adanya pengaruh EKTS terhadap minat<br>-Perjelas metode&nbsp;<br><br>Penguji 2<br>-Pada teori tuliskan ilustrasi terhadap pendapat yang ditulis<br>-Tambahkan sub bab mengenai Instalasi Motor Listrik<br>-Flowchart perbaiki&nbsp;<br>-Kisi-kisi tambahkan&nbsp;<br>-Lampiran lengkapi<br><br>Penguji 3<br>-Teori lebih ditambahkan lagi&nbsp;<br>-Lengkapi mengenai media terhadap minat&nbsp;<br>-kurang lengkap mengenai penyelesaian masalah<br>&nbsp;<br></p>', '2023-12-22 17:52:25', '2024-01-15 11:09:33');
