INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (47, 1, 43, 25, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada Jumat, 12 Januari 2024<br></p>', '2024-01-05 09:10:02', '2024-01-14 10:32:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (48, 1, 10, 24, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre-Defense dilaksanakan pada hari Rabu tanggal 17 Januari</p><p style=\"margin:0\">Dihadiri oleh dosen.</p><p style=\"margin:0\">Pembimbing :&nbsp;</p><p style=\"margin:0\">- Silmi Ath Thahirah Al Azhima</p><p style=\"margin:0\">Penguji :</p><p style=\"margin:0\">- Enjang A. Juanda</p><p style=\"margin:0\">-Siscka Elvyanti</p><p style=\"margin:0\">Adapun catatan dari dosen penguji :</p><p style=\"margin:0\">- Judul BAB di daftar isi tidak muncul</p><p style=\"margin:0\">- Kajian pustaka belum menjelaskan contoh penggunaan teori yang digunakan</p><p style=\"margin:0\">- Daftar pustaka banyak yang belum lengkap</p><p style=\"margin:0\">- Tambahkan analisis minimal dan maksimal jarak agar deteksi aplikasi</p><p style=\"margin:0\">- Tambahkan perbedaan sudut ketika penempatan kamera berbeda dengan video referensi</p><p style=\"margin:0\">- Tambahkan flowchart cara menggunakan aplikasi</p>', '2024-01-05 13:29:10', '2024-01-20 08:53:37');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (49, 1, 77, 24, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang dilaksanakan pada tanggal 12 Januari 2024 yang pelaksanaannya direschedule menjadi pukul 09.20 sampai pukul 10.30 WIB. Dosen penguji yang hadir pada sidang ini ialah pak Erik Haritman, ibu Tuti Suartini dan pak Saripudin. Selain itu dosen pembimbing yang hadir pada sidang pre-defence ialah pak Agus Heri Setya Budi dan ibu Silmi Ath Thahirah Al Azhima. Sidang dibuka oleh pak Agus Heri yang selanjutnya saat sesi tanya jawab dimoderatori oleh bu Silmi dan ditutup oleh saya sebagai mahasiswa yang diuji.</p>', '2024-01-08 11:31:26', '2024-01-13 10:40:28');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (50, 1, 148, 24, 4, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tanggal 12 Januari 2024. Penguji yang hadir adalah Pak Didin Wahyudin dan Pak Muhammad Adli. Pembimbing yang hadir adalah Pak Enjang A. Juanda. Sidang dimulai jam 10:10 sampai dengan 10:50. Dibuka oleh pak Enjang, Ditutup oleh saya (Mahasiswa).<br></p>', '2024-01-08 12:45:54', '2024-01-13 12:34:39');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (51, 1, 68, 24, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang dimulai pukul 08.15-09.15 di Lab Eldas</p><p style=\"margin:0\">Sidang dibuka oleh Prof. Enjang A. Juanda</p><p style=\"margin:0\">Dosen penguji yang hadir merupakan bapak Iwan Kustiawan dan pak Roer Eka Pawinanto</p><p style=\"margin:0\">Sidang ditutup oleh Prof. Enjang A. Juanda</p>', '2024-01-08 13:12:38', '2024-01-19 16:33:11');
