INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (53, 1, 41, 26, 1, 1, 1, 1, 1, '<p class=\"MsoNormal\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sidang predefense dilaksanakan di\nhari rabu tanggal 17 januari 2024 dihadiri oleh dosen pembimbing <span style=\"font-size: 12pt; line-height: 107%; font-family: &quot;Segoe UI&quot;, sans-serif;\">Yadi Mulyadi<br>\nMaman Somantri( tidak hadir)<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">dosen penguji <span style=\"font-size: 12pt; line-height: 107%; font-family: &quot;Segoe UI&quot;, sans-serif;\">Jaja Kustija<br>\nElih Mulyana<br>\nSilmi Ath Thahirah Al Azhi<o:p></o:p></span></p><p class=\"MsoNormal\">catatan dari dosen&nbsp;penguji&nbsp;<o:p></o:p></p><p class=\"MsoNormal\">1. Menambahkan materi tentang rangkaian pengganti<o:p></o:p></p><p class=\"MsoNormal\">2.&nbsp;symbol yang digunakan harus konsisten<o:p></o:p></p><p class=\"MsoNormal\">3. tabel yang berlebih ke halaman selanjutnya dikasih\nketerangan<o:p></o:p></p><p class=\"MsoNormal\">4. penjelasan sub bab tidak ada pada bab 3<o:p></o:p></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\">5. rumus diperhatikan lagi&nbsp;&nbsp;<o:p></o:p></p>', '2024-01-09 09:23:08', '2024-01-21 19:31:40');
