INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (26, 52, 1, '<p style=\"margin:0\">Ini bagaimana konsepnya? Apa perang Mikrotik untuk jaringan IoT ini... Bukankah cost-nya menjadi mahal?</p>', '2023-09-27 14:56:35', '2023-09-27 14:56:35');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (27, 52, 1, '<p style=\"margin:0\">Mengapa membuat vending machine harus pakai mikrotik?</p>', '2023-09-27 14:57:05', '2023-09-27 14:57:05');
