INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (75, 3, 25, '<p style=\"margin:0\">Hasil review proposal saya telah disetujui oleh Prof. Enjang selaku reviewer dari proposal saya.&nbsp;<a href=\"https://drive.google.com/file/d/18uEIXjjaGRCuzxAV6uBmYAMV_Qqsb3uM/view?usp=sharing\" target=\"_blank\">Hasil review proposal Muhammad Amir Wildan</a></p>', '2023-10-08 07:35:44', '2023-10-08 07:35:44');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (76, 36, 1, '<p style=\"margin:0\">Dalam hal ini, saran Prof. Ade harus diikuti. Karena memang ada kesalahan tahapan yang anda ambil. Pengerjaan skripsi/TA tanpa pembimbing walaupun anda sudah melakukan pengolahan data, dianggap tidak sah karena tidak berdasarkan penunjukkan pembimbing oleh KBK.</p>', '2023-10-08 07:38:18', '2023-10-08 07:38:18');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (78, 73, 1, '<p style=\"margin:0\">Ini maksudnya apakah sudah pernah diacc topiknya? Dan mendapatkan pembimbing di semester/tahun lalu?</p><p style=\"margin:0\">Ada bukti SK?</p>', '2023-10-08 10:55:05', '2023-10-08 10:55:05');
