INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (290, 99, 204, '<p style=\"margin:0\">Untuk realnya, pitot itu dikontrol menggunakan switch pada instrumen cluster di Pilot dan co-pilot.</p><p style=\"margin:0\">Untuk metode nya dikarenakan sistem pitot itu termasuk komponen&nbsp;<i>fix&nbsp; </i>berada di sisi kiri dan kanan <i>Fuselage</i>&nbsp;yang sistemnya hanya untuk mengukur tekanan static dan dynamic pada pesawat, tekanan udara pada ruang terbuka (disekitar pesawat), dan juga tekanan udara pada bidang yang disebabkan oleh bergeraknya bidang tersebut di udara(dynamic pressure). perubahan metode akan mempengaruhi fungsi dari alat peraga <i>Pitot</i>&nbsp;anti-icing</p>', '2023-10-18 04:48:44', '2023-10-18 04:48:44');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (291, 159, 232, '<p style=\"margin:0\">assalamualaikum ibu, proposalnya sudah selesai saya revisi dan sudah bisa ibu cek kembali</p><p style=\"margin:0\">mohon maaf baru selesai direvisi bu, saya baru cek arsys tadi malam dan baru selesai merevisi tadi</p>', '2023-10-18 05:08:14', '2023-10-18 05:08:14');
